            fx.AddRange(AbilityEffects.Select(s=>new NativeEffectFrame{type="fx",position=s.Position,from=s.From,radius=s.Radius,until=s.Until,beam=s.Beam,element=s.Element}));
            fx.AddRange(MeleeShots.Select(s=>new NativeEffectFrame{type="melee",effect=s.Fx,id=s.Id,owner=s.Owner.Seat.id,original=s.Original.Seat.id,spec=s.Spec,position=s.Position,velocity=s.Velocity,radius=s.Radius,at=s.At,shield=s.Shield,burn=s.Burn,poison=s.Poison}));
            fx.AddRange(MeleeImpacts.Select(s=>new NativeEffectFrame{type="slam",position=s.Position,radius=s.Radius,at=s.At}));
            fx.AddRange(ChipFields.Select(s=>new NativeEffectFrame{type="chip",effect=s.Effect,id=s.Id,owner=s.Owner.Seat.id,kind=s.Kind,position=s.Position,radius=s.Radius,at=s.Born,until=s.Until}));
            fx.AddRange(SirenFields.Select(s=>new NativeEffectFrame{type="siren",id=s.Id,owner=s.Owner.Seat.id,kind=s.Kind,position=s.Position,radius=s.Radius,at=s.At,until=s.Until}));
            fx.AddRange(LeetFields.Select(s=>new NativeEffectFrame{type="leet",id=s.Id,owner=s.Owner.Seat.id,kind=s.Kind,position=s.Position,from=s.From,at=s.At,until=s.Until,radius=s.Sanity,target=s.Target?.Seat.id??0,slender=s.Slender?.Id??0,hops=s.Hops,seen=s.Seen,hopAt=s.HopAt}));
            fx.AddRange(StormTrails.Select(s=>new NativeEffectFrame{type="storm",owner=s.Owner.Seat.id,position=s.Position,at=s.At,until=s.Until}));f.effects=fx.ToArray();
            if(Pve!=null)f.pve=new NativePveFrame{breaches=wardBreaches.Select(b=>b.ViewCopy()).ToArray(),machines=Pve.Machines.Where(u=>Time-u.at<4).ToArray(),boss=Pve.Boss.Seat.id,wave=Pve.Wave,phase=Pve.Phase,reveal=Pve.Reveal,stage=Pve.Stage,cinematic=Pve.Cinematic,outcome=Pve.Outcome,notice=Pve.Notice,maxHp=Pve.MaxHp,holding=Pve.Holding,hidden=Pve.Hidden,holdLeft=Pve.HoldLeft,holdDuration=Pve.HoldDuration,stageUntil=Pve.StageUntil,rows=Pve.Rows.Values.Select(r=>new NativePveRowFrame{notice=r.Notice,noticeUntil=r.NoticeUntil,id=r.Pilot.Seat.id,money=r.Money,earned=r.Earned,spent=r.Spent,kills=r.Kills,assists=r.Assists,deaths=r.Deaths,revives=r.Revives,revived=r.Revived,bought=r.Bought,healReady=r.HealReady,selfAt=r.SelfAt,open=r.Open?.Id??0,picks=r.Picks.Select(p=>new NativePvePickFrame{id=p.Id,tier=p.Tier,source=p.Source,offers=p.Offers?.ToArray(),at=p.At}).ToArray()}).ToArray(),pickups=Pve.Pickups.Select(p=>new NativePickupFrame{id=p.Id,owner=p.Owner.Seat.id,machine=p.Machine,tier=p.Tier,position=p.Position,born=p.Born}).ToArray()};f.CapturePresence();return f;
        }
        public void ApplyFrame(NativeGameFrame f,int localId)
        {
            f.RestorePresence();

            Replica=true;LocalId=localId;bool reset=replicaFrame==null||replicaFrame.generation!=f.generation;Match.ApplyNetwork(f);
            foreach(var sf in f.seats){var seat=Match.Seat(sf.id);if(seat==null){seat=new NativeSeat{id=sf.id};Match.Seats.Add(seat);}seat.name=sf.name;seat.spec=sf.spec;seat.team=sf.team;seat.bot=sf.bot;seat.connected=sf.connected;seat.alive=sf.alive;seat.score=sf.score;seat.roundWins=sf.roundWins;seat.AuthorityBoss=sf.boss;seat.bodyColor=sf.bodyColor;seat.accentColor=sf.accentColor;seat.hat=sf.hat;seat.lobbyPose=NativeLobbyPoses.Normalize(sf.lobbyPose);seat.lobbyBack=NativePortraitBacks.Normalize(sf.lobbyBack);seat.hatColor=NativeHatLooks.Normalize(sf.hatColor);seat.backColor=NativeHatLooks.Normalize(sf.backColor);seat.weaponSkins=NativeWeaponSkins.Normalize(sf.weaponSkins);seat.killEffect=sf.killEffect;seat.intro=sf.intro;seat.overrideIntro=sf.overrideIntro;NativeIntroRules.Migrate(ref seat.intro,ref seat.overrideIntro);seat.introText=sf.introText;seat.offers=sf.offers.ToList();seat.chips.Clear();foreach(var c in sf.chips)seat.chips[c.id]=c.count;}
            Match.Seats.RemoveAll(s=>!f.seats.Any(x=>x.id==s.id));if(reset){Reset();Generation=f.generation;}
            if(f.pve!=null&&Pve==null)ConfigurePve(JsonUtility.FromJson<NativePveContent>(Resources.Load<TextAsset>("PveContent").text),false);
            foreach(var pf in f.pilots)
            {
                var p=Pilots.Find(p=>p.Seat.id==pf.id)??SpawnPilot(Match.Seat(pf.id),Pilots.Count);p.Weapon=Content.Weapon(p.Seat.spec);p.Stats=NativeContentRules.Stats(Content,p.Seat.spec,p.Seat.chips);p.Body.isKinematic=true;p.Collider.enabled=pf.hp>0&&p.Seat.connected;
                if(pf.stats!=null)foreach(var stat in pf.stats)p.Stats[stat.name]=stat.value;ApplyDots(p.Dots,pf.dots);p.SlowEnd=pf.slowEnd;p.SlowFactor=pf.slowFactor;p.AttackAt=pf.attackAt;p.Fighter=pf.fighter;p.Death=pf.death;if(p.Death?.actor!=null)p.Death.actor.HatColor=p.Seat.hatColor;p.RevivedAt=pf.revivedAt;p.Wounds.Clear();if(pf.wounds!=null)p.Wounds.AddRange(pf.wounds);p.Hp=pf.hp;p.Mana=pf.mana;p.Stamina=pf.stamina;p.Ammo=pf.ammo;p.ECharges=pf.charges;p.Yaw=pf.yaw;p.Pitch=pf.pitch;p.Ready=pf.ready;p.QReady=pf.qReady;p.EReady=pf.eReady;p.KernelReady=pf.kernelReady;p.OverdriveAt=pf.overdriveAt;p.OverdriveUntil=pf.overdriveUntil;p.VentUntil=pf.ventUntil;p.ReloadAt=pf.reloadAt;p.ReloadEnd=pf.reloadEnd;p.BlockEnd=pf.blockEnd;p.BlockReady=pf.blockReady;p.RollAt=pf.rollAt;p.RollEnd=pf.rollEnd;p.StunEnd=pf.stunEnd;p.Down=pf.down;p.HoldAt=pf.holdAt;p.ScareAt=pf.scareAt;p.ScareUntil=pf.scareUntil;p.FrozenUntil=pf.frozenUntil;
                p.Pose=f.snapshot.Actors.FirstOrDefault(a=>a.Id==pf.id)??p.Pose;p.Kernel=p.Pose.Kernel?.ViewCopy();p.Collider.enabled=pf.hp>0&&p.Seat.connected&&!KernelLocked(p);p.AirJumps=p.Pose.AirJumps;p.AirJumpAt=p.Pose.AirJumpAt;p.MeleeKit=p.Pose.MeleeKit?.ViewCopy()??new NativeMeleeKit();if(reset||Vector3.Distance(p.Body.position,pf.position)>5)SetReplicaPosition(p.Body,pf.position);
            }
            foreach(var pf in f.pilots)Pilots.Find(p=>p.Seat.id==pf.id).Controlling=Pilots.Find(p=>p.Seat.id==pf.controlling);
            foreach(var p in Pilots.Where(p=>!f.pilots.Any(x=>x.id==p.Seat.id)).ToArray()){Pilots.Remove(p);CapturedAnimation.Release(p.Body.gameObject);}
            RestoreStructures(f.segments,(float)f.time,f.props);
            foreach(var b in Map.blocks.Where(b=>b.role!="static"&&f.props.Any(p=>p.id==b.id)))if(!Props.Any(p=>p.Definition.id==b.id))AddProp(b);
            foreach(var p in Props.ToArray()){if(!p.Replicated)continue;var pf=Array.Find(f.props,x=>x.id==p.Definition.id);if(pf==null){Props.Remove(p);p.GetComponent<Collider>().enabled=false;CapturedAnimation.Release(p.gameObject);continue;}if(p.Body!=null)p.Body.isKinematic=true;if(p.Fragment||string.IsNullOrEmpty(p.Definition.segment))p.transform.SetPositionAndRotation(pf.position,pf.rotation);if(!p.Indestructible)p.Health=pf.health;}
            foreach(var pf in f.props)if(pf.definition!=null&&!Props.Any(p=>p.Definition.id==pf.id)){var prop=AddProp(pf.definition,true);prop.Body.isKinematic=true;prop.transform.SetPositionAndRotation(pf.position,pf.rotation);}
            ApplyMinions(f);ApplyEffects(f);ApplyPve(f.pve);BossSongAt=f.bossSongAt;BossSongLead=f.bossSongLead;Events.Clear();Events.AddRange(f.snapshot.Events);Entries.Clear();if(f.entries!=null)Entries.AddRange(f.entries);MinionDeaths.Clear();if(f.corpses!=null)MinionDeaths.AddRange(f.corpses);foreach(var sf in f.seats)Match.Seat(sf.id).connected=sf.connected;replicaFrame=f;PoseStageLoads(f.time);BufferReplica(f,reset);
        }
        private void ApplyMinions(NativeGameFrame f)
        {
            foreach(var m in Minions.Where(m=>!f.minions.Any(x=>x.id==m.Id)).ToArray())RemoveMinion(m,false);
            foreach(var mf in f.minions)
            {
                var m=Minions.Find(m=>m.Id==mf.id);if(m==null){var go=new GameObject("Remote summon");go.layer=11;go.transform.SetParent(root.transform);var body=go.AddComponent<Rigidbody>();body.isKinematic=true;var collider=go.AddComponent<CapsuleCollider>();collider.radius=.42f;collider.height=1.7f;m=new NativeMinion{Id=mf.id,Body=body,Collider=collider};go.AddComponent<NativeMinionBody>().Minion=m;Minions.Add(m);}
                m.Owner=Pilots.Find(p=>p.Seat.id==mf.owner);ApplyDots(m.Dots,mf.dots);m.SlowUntil=mf.slowUntil;m.SlowFactor=mf.slowFactor;m.Kind=mf.kind;m.Hp=mf.hp;m.MaxHp=mf.maxHp;m.Yaw=mf.yaw;m.Speed=mf.speed;m.LastHitAt=mf.lastHitAt;m.LastAttack=mf.lastAttack;if(replicaFrame==null||!replicaFrame.minions.Any(x=>x.id==mf.id))SetReplicaPosition(m.Body,mf.position);m.NetworkVelocity=mf.velocity;
                if(mf.addKind!=null&&Pve!=null){var stats=Pve.Content.adds.FirstOrDefault(s=>s.id==mf.addKind);if(stats!=null)m.Pve=new NativePveAdd{Stats=stats,Entry=Pve.Content.entries.FirstOrDefault(e=>e.e==mf.entry)??Pve.Content.entries[0],ActiveAt=mf.activeAt,SpawnAt=mf.spawnAt,DiveAt=mf.diveAt,First=mf.first,Travelling=mf.travelling,Lost=mf.lost,Crawl=mf.crawl,PossessedAt=mf.possessedAt,Possessed=mf.possessed};}
                if(m.Pve?.Stats.id=="hulk"&&!m.Pve.Crawl){m.Collider.radius=NativeHordeKinds.HulkRadius;m.Collider.height=NativeHordeKinds.HulkHeight;}
            }
        }
        private void ApplyEffects(NativeGameFrame f)
        {
            AbilityShots.Clear();AbilityZones.Clear();AbilityEffects.Clear();MeleeShots.Clear();MeleeImpacts.Clear();ChipFields.Clear();SirenFields.Clear();LeetFields.Clear();StormTrails.Clear();Bullets.Clear();
            foreach(var e in f.effects){var p=Pilots.Find(p=>p.Seat.id==e.owner);var d=Content.abilities.FirstOrDefault(d=>d.id==e.ability);
                if(e.type=="fx")AbilityEffects.Add(new NativeAbilityFx{Position=e.position,From=e.from,Radius=e.radius,Until=e.until,Beam=e.beam,Element=e.element});
                else if(e.type=="slam")MeleeImpacts.Add(new NativeMeleeImpact{Position=e.position,Radius=e.radius,At=e.at});
                else if(p==null)continue;
                else if(e.type=="ability"&&d!=null)AbilityShots.Add(new NativeAbilityShot{Id=e.id,Owner=p,Definition=d,Position=e.position,Velocity=e.velocity,Radius=e.radius,Fuse=e.fuse});
                else if(e.type=="zone"&&d!=null)AbilityZones.Add(new NativeAbilityZone{Id=e.id,Born=e.at,LockAt=e.lockAt,Attached=Pilots.Find(q=>q.Seat.id==e.attached),AttachedMinion=Minions.Find(m=>m.Id==e.attachedMinion),Owner=p,Definition=d,Kind=e.kind,Position=e.position,Radius=e.radius,Until=e.until});
                else if(e.type=="melee")MeleeShots.Add(new NativeMeleeShot{Id=e.id,Owner=p,Original=Pilots.Find(q=>q.Seat.id==e.original)??p,Spec=e.spec,Fx=string.IsNullOrEmpty(e.effect)?null:e.effect,Position=e.position,Velocity=e.velocity,Radius=e.radius,At=e.at,Shield=e.shield,Burn=e.burn,Poison=e.poison});
                else if(e.type=="chip")ChipFields.Add(new NativeChipField{Effect=e.effect,Id=e.id,Owner=p,Kind=e.kind,Position=e.position,Radius=e.radius,Born=e.at,Until=e.until});
                else if(e.type=="siren")SirenFields.Add(new NativeSirenField{Id=e.id,Owner=p,Kind=e.kind,Position=e.position,Radius=e.radius,At=e.at,Until=e.until});
                else if(e.type=="leet")LeetFields.Add(new NativeLeetField{Id=e.id,Owner=p,Kind=e.kind,Position=e.position,From=e.from,At=e.at,Until=e.until,Sanity=e.radius,Target=Pilots.Find(x=>x.Seat.id==e.target),Slender=Minions.Find(x=>x.Id==e.slender),Hops=e.hops,Seen=e.seen,HopAt=e.hopAt});
                else if(e.type=="storm")StormTrails.Add(new NativeStormTrail{Owner=p,Position=e.position,At=e.at,Until=e.until});
            }
            // JsonUtility represents absent string tags as empty strings; runtime special-shot dispatch uses null.
            foreach(var s in f.snapshot.Shots)Bullets.Add(new NativeBullet{Id=s.Id,Owner=s.Owner,Original=s.Original,SirenTarget=s.SirenTarget,Position=Vec(s.Position),Velocity=Vec(s.Velocity),Radius=s.Radius,Spec=s.Spec??"pistol",SirenKind=string.IsNullOrEmpty(s.SirenKind)?null:s.SirenKind,LeetKind=string.IsNullOrEmpty(s.LeetKind)?null:s.LeetKind,Born=s.Born,Burn=s.Burn,Poison=s.Poison,Hadoken=s.Hadoken,Super=s.Super,Direct=s.Direct,ChipImpact=s.ChipImpact,WeaponFx=s.WeaponFx,Pong=s.Pong,Boomerang=s.Boomerang,Zigzag=s.Zigzag,Mods=(s.Mods??Array.Empty<ChipCount>()).ToDictionary(c=>c.id,c=>c.count)});
        }
        private void ApplyPve(NativePveFrame f)
        {
            if(f==null||Pve==null)return;wardBreaches.Clear();if(f.breaches!=null)wardBreaches.AddRange(f.breaches.Select(b=>b.ViewCopy()));PoseWardBreaches();var v=Pve;v.Boss=Pilots.Find(p=>p.Seat.id==f.boss);v.Wave=f.wave;v.Phase=f.phase;v.Reveal=f.reveal;v.Stage=f.stage;v.Cinematic=f.cinematic;v.Outcome=f.outcome;v.Notice=f.notice;v.MaxHp=f.maxHp;v.Hidden=f.hidden;v.Holding=f.holding;v.HoldLeft=f.holdLeft;v.HoldDuration=f.holdDuration;v.StageUntil=f.stageUntil;v.Rows.Clear();v.Machines.Clear();if(f.machines!=null)v.Machines.AddRange(f.machines);
            foreach(var rf in f.rows){var p=Pilots.Find(p=>p.Seat.id==rf.id);if(p==null)continue;var r=new NativePveRow{Notice=rf.notice,NoticeUntil=rf.noticeUntil,Pilot=p,Money=rf.money,Earned=rf.earned,Spent=rf.spent,Kills=rf.kills,Assists=rf.assists,Deaths=rf.deaths,Revives=rf.revives,Revived=rf.revived,Bought=rf.bought,HealReady=rf.healReady,SelfAt=rf.selfAt};foreach(var pf in rf.picks){var pick=new NativePvePick{Id=pf.id,Tier=pf.tier,Source=pf.source,Offers=pf.offers?.ToList(),At=pf.at};r.Picks.Add(pick);if(pf.id==rf.open)r.Open=pick;}v.Rows[p.Seat.id]=r;}
            v.Pickups.Clear();foreach(var pf in f.pickups){var owner=Pilots.Find(p=>p.Seat.id==pf.owner);if(owner!=null)v.Pickups.Add(new NativePvePickup{Id=pf.id,Machine=pf.machine,Owner=owner,Tier=pf.tier,Position=pf.position,Born=pf.born});}
        }
        private Snapshot ReplicaSnapshot()
        {var snapshot=replicaFrame.snapshot;return new Snapshot{Tick=snapshot.Tick,Actors=snapshot.Actors.Select(a=>{var p=Pilots.Find(p=>p.Seat.id==a.Id);var v=a.ViewCopy();if(p!=null){v.HatColor=p.Seat.hatColor;v.Position=Vec(p.Body.position-Vector3.up*.865f);v.Yaw=v.AimYaw=p.Yaw;v.Pitch=p.Pitch;if(p.Seat.id==LocalId){if(p.Seat.spec=="bow")v.BowDrawAt=predictor.State.BowDrawAt;if(p.Seat.spec=="cyberlord"&&predictor.State.Cyber!=null){v.Cyber=predictor.State.Cyber.ViewCopy();v.AttackAt=v.Cyber.At;v.AttackUntil=v.Cyber.Until;}PredictedJumpPose(v);PredictedMeleePose(v);}}return v;}).ToArray(),Covers=snapshot.Covers,Shots=snapshot.Shots,Events=snapshot.Events};}
    }
